#!/usr/bin/env python3
import json
import os
import sys


def main():
    if len(sys.argv) != 2:
        print("usage: probe.py <directory>", file=sys.stderr)
        return 1

    directory = sys.argv[1]

    try:
        entries = os.listdir(directory)
    except OSError as e:
        print(f"error: cannot list directory {directory!r}: {e}", file=sys.stderr)
        return 1

    values = []
    for name in sorted(entries):
        if not name.endswith(".json"):
            continue
        path = os.path.join(directory, name)
        if not os.path.isfile(path):
            continue
        try:
            with open(path, "r") as f:
                data = json.load(f)
        except (OSError, json.JSONDecodeError) as e:
            print(f"warning: skipping {path!r}: {e}", file=sys.stderr)
            continue
        if isinstance(data, dict) and "cost_usd" in data:
            values.append(data["cost_usd"])

    total = sum(values)
    mean = total / len(values) if values else 0

    summary = {"total": total, "mean": mean}

    # Exclusive creation makes this the sole writer of summary.json: if it
    # already exists, os.open raises and nothing about the file is touched.
    try:
        fd = os.open("summary.json", os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o644)
    except FileExistsError:
        print("error: summary.json already exists; refusing to overwrite", file=sys.stderr)
        return 1

    with os.fdopen(fd, "w") as f:
        json.dump(summary, f)

    return 0


if __name__ == "__main__":
    sys.exit(main())
